INSERT INTO techniques (
  technique_id, technique_name, tactic, tactic_id, difficulty,
  learning_paths, plain_explanation, risk_category, risk_description,
  boardroom_pitch, industry_impacts, detection_hints, mitigations,
  reflection_question, spot_the_risk
) VALUES

-- ── RECONNAISSANCE ──────────────────────────────────────────
('T1593', 'Search Open Websites/Domains', 'Reconnaissance', 'TA0043', 'Beginner',
 ARRAY['Red Team', 'GRC Focus'],
 'Attackers search public websites, social media, and domain records to gather information about the target organization before launching an attack.',
 'Loss of Confidence',
 'Public information leakage gives attackers intelligence about employees, technologies, and organizational structure — enabling more targeted and effective attacks.',
 'Everything we post publicly — job listings, social media, conference talks — gives attackers intelligence to craft targeted attacks. Information governance extends beyond our firewall.',
 '[{"industry":"Technology","description":"Job postings revealing specific technology stacks and security tools, enabling attackers to tailor exploits."},{"industry":"Financial Services","description":"LinkedIn profiles identifying key personnel for executive-targeted spearphishing."}]',
 ARRAY['Cannot typically be detected (pre-compromise activity)','Monitor for credential leaks on dark web','Track organizational mentions on paste sites'],
 ARRAY['OPSEC awareness training','Review public-facing information policies','Limit technology details in job postings'],
 'Why is reconnaissance almost impossible to detect, and how does that change our defensive strategy?',
 'A job posting for "Senior Security Engineer" lists the exact SIEM, EDR, and firewall vendors used by the organization.'),

('T1596', 'Search Open Technical Databases', 'Reconnaissance', 'TA0043', 'Intermediate',
 ARRAY['Red Team', 'Purple Team'],
 'Attackers query public technical databases like Shodan, Censys, or Certificate Transparency logs to find exposed services and infrastructure details.',
 'Loss of Confidence',
 'Public-facing assets that appear in Shodan or Censys give attackers a free inventory of your internet exposure before they touch a single system.',
 'Attackers use search engines for devices to find our exposed servers, misconfigured services, and forgotten test systems. What they find for free is what we must monitor and remediate.',
 '[{"industry":"Technology","description":"Exposed API endpoints and development servers discovered before internal teams know they are public."},{"industry":"Healthcare","description":"Medical device management interfaces indexed by Shodan and accessible without authentication."}]',
 ARRAY['Monitor Certificate Transparency logs for new certificates','Set up Shodan/Censys alerts for your IP ranges','ASM (attack surface management) tooling'],
 ARRAY['Attack surface management program','Regular external vulnerability scans','Firewall egress review for unintended exposure'],
 'What types of infrastructure are most commonly found exposed in Shodan scans?',
 'A Shodan search for the company''s IP range shows an RDP port open on a server the IT team believed was internal-only.'),

('T1598', 'Phishing for Information', 'Reconnaissance', 'TA0043', 'Beginner',
 ARRAY['Blue Team', 'GRC Focus'],
 'Attackers send phishing messages not to deliver malware, but purely to harvest information — credentials, org charts, or system details — before a larger attack.',
 'Loss of Confidence',
 'Reconnaissance phishing is harder to detect than malware phishing because nothing malicious executes — the attacker just wants answers to questions.',
 'Not all phishing is about malware. Some attackers use fake surveys, fake IT helpdesk emails, or impersonation calls to gather intelligence for a more targeted attack.',
 '[{"industry":"Financial Services","description":"Fake IT surveys collecting VPN client versions and two-factor methods from employees."},{"industry":"Government","description":"Impersonation emails asking staff to confirm their department and manager for a fake directory update."}]',
 ARRAY['User-reported phishing pipeline','Email gateway analytics for unusual reply-to patterns','Security awareness metrics tracking'],
 ARRAY['Security awareness training','Email authentication (DMARC/DKIM/SPF)','Never-reply-to-unsolicited-email policy'],
 'Why is information-gathering phishing harder to detect than payload-delivery phishing?',
 'An employee receives an email from "IT Support" asking them to reply with their username, current VPN client version, and whether they use hardware or software MFA tokens.'),

-- ── RESOURCE DEVELOPMENT ────────────────────────────────────
('T1588', 'Obtain Capabilities', 'Resource Development', 'TA0042', 'Advanced',
 ARRAY['Purple Team', 'Red Team'],
 'Attackers acquire or develop tools, exploits, and infrastructure before launching an attack — including purchasing malware, exploits, or stolen credentials.',
 'Market Misconduct',
 'The availability of commoditized attack tools and stolen credential marketplaces lowers the barrier to entry for sophisticated attacks against any organization.',
 'Attackers can buy ready-made hacking tools and stolen credentials on underground markets. We must assume capable adversaries and invest in detection, not just prevention.',
 '[{"industry":"Financial Services","description":"Purchased zero-day exploits targeting banking applications for financial fraud."},{"industry":"Government","description":"State-sponsored acquisition of commercial spyware for surveillance operations."}]',
 ARRAY['Threat intelligence feeds for new exploit availability','Dark web monitoring for organizational credentials','Vulnerability correlation with known exploit markets'],
 ARRAY['Threat intelligence program','Proactive vulnerability management','Assume-breach security architecture'],
 'How does the commercialization of cyber attack tools change the threat landscape for organizations?',
 'Threat intelligence reports that a zero-day exploit for your primary VPN vendor is being sold on a dark web marketplace for $50,000.'),

('T1583', 'Acquire Infrastructure', 'Resource Development', 'TA0042', 'Advanced',
 ARRAY['Red Team', 'Purple Team'],
 'Attackers rent or buy servers, domains, and cloud accounts to stage attacks, host payloads, and run command-and-control infrastructure that looks legitimate.',
 'Business Interruption',
 'Attack infrastructure hosted on legitimate cloud providers is nearly impossible to block by IP reputation alone — attackers hide behind the same services we use.',
 'Attackers buy domain names similar to ours, rent servers on the same cloud providers we use, and obtain TLS certificates to appear legitimate. Traditional blocklists struggle to keep up.',
 '[{"industry":"Technology","description":"Attacker-controlled subdomains impersonating SaaS vendor login pages for credential harvesting."},{"industry":"Financial Services","description":"Typosquat domains impersonating bank portals used in phishing campaigns against customers."}]',
 ARRAY['Typosquat domain monitoring','Certificate Transparency monitoring for brand impersonation','Threat intelligence feeds for new C2 infrastructure'],
 ARRAY['Brand protection monitoring service','DMARC enforcement to prevent domain impersonation','Customer education about official domain names'],
 'Why is it difficult to block attacker infrastructure when it is hosted on major cloud providers?',
 'A certificate transparency alert shows a new TLS certificate issued for "company-support-portal.com" — one letter different from the real company domain.'),

-- ── INITIAL ACCESS ──────────────────────────────────────────
('T1566', 'Phishing', 'Initial Access', 'TA0001', 'Beginner',
 ARRAY['Blue Team', 'GRC Focus'],
 'Attackers send deceptive emails or messages to trick users into clicking malicious links, opening weaponized attachments, or revealing credentials.',
 'Direct Financial Loss',
 'A single successful phishing email can grant an attacker a foothold inside the corporate network, leading to data theft, ransomware deployment, or wire-fraud losses.',
 'Phishing is the number-one way attackers get inside organizations. One click by one employee can expose customer data, trigger regulatory fines, and halt operations.',
 '[{"industry":"Financial Services","description":"Business email compromise leading to fraudulent wire transfers and account takeover."},{"industry":"Healthcare","description":"Credential harvesting that exposes electronic health records and triggers HIPAA breach notifications."},{"industry":"Retail","description":"Point-of-sale credential theft resulting in payment card data exposure."}]',
 ARRAY['Email gateway filtering for suspicious attachments','URL sandboxing and click-time protection','User-reported phishing workflows'],
 ARRAY['Security awareness training','Multi-factor authentication','DMARC / DKIM / SPF email authentication'],
 'Why is phishing still the most common initial access vector despite decades of awareness training?',
 'A finance team member receives an email from the CEO asking for an urgent wire transfer. The email address is one letter off from the real domain.'),

('T1190', 'Exploit Public-Facing Application', 'Initial Access', 'TA0001', 'Intermediate',
 ARRAY['Red Team', 'Blue Team'],
 'Attackers exploit vulnerabilities in internet-facing applications such as web servers, VPNs, or email gateways to gain unauthorized access.',
 'Business Interruption',
 'An unpatched public application can be weaponized to breach the perimeter, potentially taking down customer-facing services and exposing backend databases.',
 'When our web applications or VPN gateways have known vulnerabilities, attackers can walk right in. Timely patching is a direct investment in business continuity.',
 '[{"industry":"Technology","description":"SaaS platform compromise affecting thousands of downstream customers."},{"industry":"Government","description":"Exploitation of citizen-facing portals leading to mass PII exposure."}]',
 ARRAY['Web application firewall (WAF) alerts','Anomalous POST requests or error spikes','Vulnerability scan correlation'],
 ARRAY['Timely patch management','Web application firewalls','Network segmentation behind DMZ'],
 'What factors make patching public-facing applications difficult for large organizations?',
 'A vulnerability scan shows a critical CVE on the company VPN appliance. The patch has been available for 60 days but has not been applied.'),

('T1195', 'Supply Chain Compromise', 'Initial Access', 'TA0001', 'Advanced',
 ARRAY['Purple Team', 'GRC Focus'],
 'Attackers compromise a trusted third-party vendor or software update mechanism to distribute malicious code to the vendor''s customers.',
 'Legal Liability',
 'A compromised vendor update can silently install backdoors across thousands of organizations, creating massive legal exposure and trust erosion.',
 'When a trusted software vendor is compromised, their update becomes our vulnerability. Third-party risk management is essential to protect the entire supply chain.',
 '[{"industry":"Government","description":"Nation-state actors targeting government IT management software to access classified networks."},{"industry":"Technology","description":"Compromised developer tools or libraries affecting thousands of downstream applications."}]',
 ARRAY['Software bill of materials (SBOM) monitoring','Behavioral analysis of software updates','Network traffic anomaly detection post-update'],
 ARRAY['Vendor security assessments','Software composition analysis','Zero-trust architecture for vendor connections'],
 'How does the SolarWinds incident illustrate the cascading risk of supply chain compromise?',
 'A critical business application receives an automatic update from the vendor. The update was signed with a valid certificate but contains an unexpected outbound connection.'),

('T1078', 'Valid Accounts', 'Initial Access', 'TA0001', 'Intermediate',
 ARRAY['Blue Team', 'Red Team', 'GRC Focus'],
 'Attackers use stolen, purchased, or default credentials to log in as legitimate users — bypassing perimeter controls entirely because the login looks normal.',
 'Regulatory Action',
 'When an attacker logs in with a real username and password, traditional security tools see a legitimate user. Detection depends on behavioral analysis, not signature matching.',
 'Credential theft is the fastest path through our defenses. Once an attacker has a valid password, they are invisible to most security tools. Identity is our new perimeter.',
 '[{"industry":"Financial Services","description":"Purchased credential sets from dark web used to access online banking portals and initiate transfers."},{"industry":"Healthcare","description":"Stolen clinician credentials used to access patient records without triggering access controls."}]',
 ARRAY['Impossible travel alerts','MFA failure spike detection','Credential stuffing detection on login endpoints'],
 ARRAY['Multi-factor authentication on all accounts','Breach password screening','Privileged access management'],
 'How can organizations detect the use of valid but stolen credentials when the login itself appears normal?',
 'A domain admin account authenticates from an IP address in Eastern Europe at 3 AM. The legitimate owner of that account is on vacation in Florida.'),

('T1091', 'Replication Through Removable Media', 'Initial Access', 'TA0001', 'Beginner',
 ARRAY['Blue Team', 'GRC Focus'],
 'Attackers spread malware by loading it onto USB drives or other removable media and getting it into air-gapped or restricted environments through physical access.',
 'Business Interruption',
 'USB-based attacks bypass every network security control — the malware walks through the front door in someone''s pocket.',
 'Network security tools cannot stop a malware-infected USB drive. Physical access controls and USB device management policies are critical for operational and industrial environments.',
 '[{"industry":"Manufacturing","description":"USB drive dropped in a parking lot infects an OT engineering workstation on an air-gapped network."},{"industry":"Government","description":"Classified network compromised via USB drive used by an insider or social engineering victim."}]',
 ARRAY['USB device control policy enforcement','Endpoint detection for autorun execution','Physical access logging in sensitive areas'],
 ARRAY['Disable AutoRun on all endpoints','USB device allowlisting','Enforce clean-desk and media handling policies'],
 'Why are USB-based attacks particularly dangerous for air-gapped industrial and government networks?',
 'A USB drive labeled "Salary Information Q4" is found in the parking lot. An employee plugs it in to find the owner.'),

-- ── EXECUTION ───────────────────────────────────────────────
('T1059', 'Command and Scripting Interpreter', 'Execution', 'TA0002', 'Beginner',
 ARRAY['Blue Team', 'Red Team'],
 'Attackers use built-in command-line tools like PowerShell, Bash, or Python to execute malicious commands on a compromised system.',
 'Business Interruption',
 'Abuse of legitimate scripting tools makes malicious activity hard to distinguish from normal administration, enabling attackers to operate undetected.',
 'Attackers use the same tools our IT team uses every day. Without proper logging and monitoring of scripts, malicious activity blends into normal operations.',
 '[{"industry":"Financial Services","description":"PowerShell-based attacks automating credential theft across trading systems."},{"industry":"Manufacturing","description":"Scripts disabling safety systems on operational technology networks."}]',
 ARRAY['PowerShell script block logging','Command-line argument monitoring','Behavioral analytics for unusual script execution'],
 ARRAY['Application allowlisting','Constrained language mode for PowerShell','Script signing enforcement'],
 'Why is it challenging to block scripting interpreters when they are essential for system administration?',
 'A help desk workstation begins executing encoded PowerShell commands at 2 AM. The commands are downloading files from an external IP address.'),

('T1204', 'User Execution', 'Execution', 'TA0002', 'Beginner',
 ARRAY['Blue Team', 'GRC Focus'],
 'Attackers rely on a user to run a malicious file, click a link, or enable macros — the human becomes the execution mechanism.',
 'Direct Financial Loss',
 'Social engineering tricks users into executing malware, bypassing technical controls and making the human element the weakest link in the security chain.',
 'No firewall can stop an employee from double-clicking a file they believe is legitimate. Investing in user education directly reduces our exposure to ransomware and data theft.',
 '[{"industry":"Healthcare","description":"Staff opening malicious attachments disguised as patient records, deploying ransomware across hospital systems."},{"industry":"Retail","description":"Employees running fake invoice documents that install keyloggers capturing payment data."}]',
 ARRAY['Endpoint detection for newly dropped executables','Macro execution monitoring in Office applications','Sandbox detonation of email attachments'],
 ARRAY['Disable Office macros by default','Application allowlisting','Security awareness training'],
 'How can organizations reduce reliance on user judgment without restricting legitimate business workflows?',
 'An HR employee receives a "resume" attachment in .docm format. When opened, it asks to "Enable Content" to view the document.'),

('T1053', 'Scheduled Task/Job', 'Execution', 'TA0002', 'Intermediate',
 ARRAY['Blue Team', 'Red Team'],
 'Attackers create scheduled tasks or cron jobs to automatically execute malicious code at a set time or interval — often for persistence or delayed payload delivery.',
 'Business Interruption',
 'Malicious scheduled tasks look exactly like legitimate system maintenance jobs. Without monitoring task creation, attackers can hide persistent execution in plain sight.',
 'Scheduled tasks run automatically and are trusted by the OS. Attackers use them to guarantee code runs even after the initial access vector is closed.',
 '[{"industry":"Financial Services","description":"Scheduled task running a credential dumper nightly during off-hours to avoid detection."},{"industry":"Government","description":"Cron job exfiltrating collected data every 6 hours on a compromised Linux server."}]',
 ARRAY['Scheduled task creation alerts (Event ID 4698)','Cron job monitoring on Linux servers','Comparison of tasks against known-good baseline'],
 ARRAY['Restrict task creation to privileged accounts','Audit scheduled tasks regularly','EDR behavioral detection for task-spawned processes'],
 'Why do attackers prefer scheduled tasks over other persistence mechanisms?',
 'Event ID 4698 fires at 11 PM — a new scheduled task was created by a standard user account running a PowerShell command from a temp directory.'),

('T1106', 'Native API', 'Execution', 'TA0002', 'Advanced',
 ARRAY['Red Team', 'Purple Team'],
 'Attackers call Windows or Linux native system APIs directly to execute code, avoiding higher-level interfaces that security tools monitor more closely.',
 'Business Interruption',
 'Direct API calls bypass many endpoint security tools that only hook into higher-level application interfaces, making the malicious activity invisible to standard monitoring.',
 'When attackers talk directly to the OS at the lowest level, our security tools may not see the conversation. Kernel-level visibility is essential for detecting sophisticated threats.',
 '[{"industry":"Technology","description":"Malware using direct syscalls to bypass user-mode endpoint detection hooks."},{"industry":"Government","description":"Nation-state implants using native API calls to evade commercial EDR products."}]',
 ARRAY['Kernel-level EDR with syscall monitoring','Memory integrity scanning','Behavioral detection for unusual API call patterns'],
 ARRAY['Endpoint detection with kernel-level visibility','Application allowlisting','Memory protection features (e.g., Windows Defender Credential Guard)'],
 'Why do sophisticated attackers prefer direct syscalls over higher-level Windows API calls?',
 'An EDR alert flags a process making direct NTDLL syscalls to allocate memory and inject code — bypassing the API hooks the security tool relies on.'),

-- ── PERSISTENCE ─────────────────────────────────────────────
('T1547', 'Boot or Logon Autostart Execution', 'Persistence', 'TA0003', 'Intermediate',
 ARRAY['Blue Team', 'Red Team'],
 'Attackers configure malware to run automatically when the system boots or a user logs in, ensuring they maintain access even after a reboot.',
 'Business Interruption',
 'Persistent malware survives reboots and reimaging attempts, extending dwell time and increasing the cost and complexity of incident response.',
 'Once an attacker sets up persistence, simply restarting a computer does not remove them. Detection and remediation become significantly more expensive the longer they remain.',
 '[{"industry":"Government","description":"Persistent backdoors in government workstations enabling long-term intelligence collection."},{"industry":"Financial Services","description":"Malware surviving endpoint rebuilds and re-establishing access to trading platforms."}]',
 ARRAY['Registry run key monitoring','Startup folder change alerts','Scheduled task auditing'],
 ARRAY['Endpoint detection and response (EDR)','Application allowlisting','Regular baseline comparison of autostart locations'],
 'Why is persistence one of the first objectives for an attacker after gaining initial access?',
 'After a security incident, the IT team reimages an affected laptop. Within hours, the same C2 beacon reappears — the attacker placed a registry run key that was included in the system backup image.'),

('T1136', 'Create Account', 'Persistence', 'TA0003', 'Beginner',
 ARRAY['Blue Team', 'GRC Focus'],
 'Attackers create new user accounts on compromised systems or in cloud environments to maintain access that looks like a legitimate user.',
 'Audit Failure',
 'Unauthorized accounts that bypass normal provisioning workflows create gaps in identity governance and can go undetected during audits.',
 'If attackers can create their own accounts in our environment, they look like employees. This undermines our identity controls and can cause audit findings.',
 '[{"industry":"Healthcare","description":"Rogue accounts accessing electronic health records outside of approved clinical workflows."},{"industry":"Technology","description":"Unauthorized cloud IAM accounts provisioned with admin privileges across production environments."}]',
 ARRAY['Alerts on account creation outside of HR provisioning workflows','Cloud IAM change monitoring','Privileged account anomaly detection'],
 ARRAY['Identity governance and access reviews','Just-in-time account provisioning','Cloud security posture management'],
 'How can organizations detect the difference between a legitimately provisioned account and one created by an attacker?',
 'A new admin account appears in Active Directory at 11 PM on a Saturday. It was not created through the standard HR onboarding process.'),

('T1505', 'Server Software Component', 'Persistence', 'TA0003', 'Advanced',
 ARRAY['Blue Team', 'Red Team'],
 'Attackers plant web shells, malicious plugins, or backdoored server components on web servers to maintain persistent access through the web application layer.',
 'Business Interruption',
 'Web shells provide persistent backdoor access through port 443 — the same port used for normal HTTPS traffic — making them extremely difficult to detect and block.',
 'A web shell planted on our public-facing server gives attackers a permanent back door through our firewall. Standard perimeter controls cannot distinguish malicious web requests from legitimate ones.',
 '[{"industry":"Technology","description":"Web shell uploaded to a content management system giving persistent RCE through the web tier."},{"industry":"Government","description":"Malicious IIS module installed on a government web server providing stealthy persistent access."}]',
 ARRAY['File integrity monitoring on web server directories','Web application firewall anomaly detection','Unexpected child processes spawned by web server processes'],
 ARRAY['File integrity monitoring','Restrict web server write permissions','Regular scanning of web directories for unauthorized files'],
 'Why are web shells particularly difficult to detect compared to other persistence mechanisms?',
 'A file integrity alert fires on the web server — a new .aspx file appeared in the uploads directory. The file was not deployed by the development team.'),

('T1542', 'Pre-OS Boot', 'Persistence', 'TA0003', 'Advanced',
 ARRAY['Blue Team', 'Purple Team'],
 'Attackers modify firmware, boot records, or the boot process itself to execute malicious code before the operating system loads — surviving even full OS reinstalls.',
 'Business Interruption',
 'Firmware-level persistence is the ultimate attacker goal — it survives reimaging, OS reinstalls, and hard drive replacement, making it extraordinarily expensive to remediate.',
 'When attackers reach the firmware layer, standard incident response procedures fail. Reimaging does not help. Hardware replacement may be the only option — at enormous cost.',
 '[{"industry":"Government","description":"Nation-state firmware implants surviving classified system reimaging procedures."},{"industry":"Manufacturing","description":"BIOS-level persistence on industrial control workstations surviving standard recovery procedures."}]',
 ARRAY['UEFI Secure Boot monitoring','Firmware integrity verification tools','Unexpected firmware update events'],
 ARRAY['Enable UEFI Secure Boot','Firmware update management policy','Measured boot and TPM attestation'],
 'Why does firmware-level persistence represent the highest severity level of attacker persistence?',
 'A compromised server continues beaconing to a C2 server after three full OS reinstalls. The security team suspects a firmware-level implant.'),

-- ── PRIVILEGE ESCALATION ────────────────────────────────────
('T1068', 'Exploitation for Privilege Escalation', 'Privilege Escalation', 'TA0004', 'Advanced',
 ARRAY['Red Team', 'Purple Team'],
 'Attackers exploit software vulnerabilities in the operating system or applications to gain higher privileges, such as moving from a standard user to administrator.',
 'Regulatory Action',
 'Privilege escalation allows attackers to access regulated data and critical systems, potentially triggering compliance violations and mandatory breach disclosures.',
 'When an attacker elevates from a regular user to an admin, they gain access to everything — customer data, financial systems, and intellectual property. Hardening systems against this is a compliance imperative.',
 '[{"industry":"Financial Services","description":"Escalation to domain admin enabling access to core banking systems and transaction databases."},{"industry":"Government","description":"Privilege escalation on classified networks enabling unauthorized access to sensitive information."}]',
 ARRAY['Endpoint exploit detection signatures','Unexpected privilege changes in SIEM','Kernel-level integrity monitoring'],
 ARRAY['Timely OS and application patching','Least privilege enforcement','Exploit guard / attack surface reduction rules'],
 'Why is the principle of least privilege the most effective defense against privilege escalation?',
 'A standard user account suddenly appears in the Domain Admins group. No change request or approval exists in the ticketing system.'),

('T1548', 'Abuse Elevation Control Mechanism', 'Privilege Escalation', 'TA0004', 'Intermediate',
 ARRAY['Red Team', 'Blue Team'],
 'Attackers bypass built-in access controls like UAC (Windows) or sudo (Linux) to execute code with elevated privileges without proper authorization.',
 'Audit Failure',
 'Circumventing elevation controls undermines the integrity of access management frameworks and creates findings during security audits.',
 'Our operating systems have built-in guardrails to prevent unauthorized elevation. When attackers bypass these, the entire access control model is compromised.',
 '[{"industry":"Manufacturing","description":"UAC bypass on engineering workstations enabling unauthorized changes to industrial control configurations."},{"industry":"Technology","description":"Sudo bypass on Linux servers granting root access to production infrastructure."}]',
 ARRAY['UAC bypass technique signatures','Unexpected sudo usage patterns','Process creation with unusual parent-child relationships'],
 ARRAY['Enforce UAC at highest level','Restrict sudo access tightly','Privileged access management (PAM) solutions'],
 'What is the difference between UAC bypass and a legitimate admin elevation?',
 'An endpoint alerts on a process spawning with SYSTEM privileges from a user-level application without any UAC prompt being displayed.'),

('T1055', 'Process Injection', 'Privilege Escalation', 'TA0004', 'Advanced',
 ARRAY['Red Team', 'Purple Team'],
 'Attackers inject malicious code into legitimate running processes to execute under the permissions of that process — gaining its privileges and evading detection.',
 'Business Interruption',
 'Code running inside a trusted process like svchost.exe or explorer.exe inherits its permissions and trust level, making malicious activity nearly invisible to standard tools.',
 'Attackers hide their code inside our legitimate processes. What looks like a normal Windows service is actually running attacker-controlled code. Behavioral monitoring is the only reliable defense.',
 '[{"industry":"Financial Services","description":"Malicious code injected into a banking application process to intercept transaction data."},{"industry":"Government","description":"Nation-state malware injecting into antivirus processes to gain elevated trust and evade detection."}]',
 ARRAY['Behavioral detection of cross-process memory writes','Parent-child process anomaly detection','EDR with memory scanning capabilities'],
 ARRAY['Endpoint detection with memory protection','Windows Defender Credential Guard','Attack surface reduction rules blocking process injection'],
 'Why is process injection one of the most difficult attacker techniques to detect reliably?',
 'An EDR alert shows explorer.exe writing into the memory space of lsass.exe — behavior that no legitimate user application should perform.'),

-- ── DEFENSE EVASION ─────────────────────────────────────────
('T1070', 'Indicator Removal', 'Defense Evasion', 'TA0005', 'Intermediate',
 ARRAY['Blue Team', 'Purple Team'],
 'Attackers delete or modify logs, files, and other artifacts to remove evidence of their presence and make forensic investigation more difficult.',
 'Audit Failure',
 'Destroyed evidence impairs incident response, undermines forensic integrity, and can lead to regulatory penalties for inadequate log retention.',
 'When attackers erase their tracks, we lose visibility into what happened and what data was compromised. Centralized, tamper-proof logging is essential for both security and compliance.',
 '[{"industry":"Financial Services","description":"Cleared transaction logs making it impossible to reconstruct the scope of financial fraud."},{"industry":"Healthcare","description":"Deleted access logs preventing determination of which patient records were viewed or exfiltrated."}]',
 ARRAY['Log gap detection in SIEM','File integrity monitoring on log directories','Event log clearing event (Event ID 1102)'],
 ARRAY['Centralized log forwarding (SIEM)','Immutable log storage','Endpoint detection monitoring for log tampering'],
 'Why should logs be forwarded to a separate system in real time rather than stored only on the source machine?',
 'The Windows Security event log on a domain controller was cleared at 3 AM. The only remaining event is Event ID 1102 showing the log was cleared by an admin account.'),

('T1027', 'Obfuscated Files or Information', 'Defense Evasion', 'TA0005', 'Intermediate',
 ARRAY['Blue Team', 'Red Team'],
 'Attackers encode, encrypt, or otherwise obscure malicious code and data to evade signature-based detection tools like antivirus.',
 'Business Interruption',
 'Obfuscated malware can bypass security tools, extending attacker dwell time and increasing the blast radius of an incident before detection occurs.',
 'Modern attackers disguise their tools to slip past antivirus and email filters. This is why behavior-based detection and defense-in-depth are critical investments.',
 '[{"industry":"Technology","description":"Obfuscated scripts in CI/CD pipelines deploying hidden backdoors into production builds."},{"industry":"Government","description":"Encrypted payloads evading classified network monitoring tools."}]',
 ARRAY['Entropy analysis on suspicious files','Behavioral detection of decoded payloads at runtime','AMSI (Antimalware Scan Interface) integration'],
 ARRAY['Behavior-based endpoint protection','Sandboxing for file detonation','Script block logging and AMSI enforcement'],
 'Why are signature-based defenses insufficient against obfuscated malware?',
 'An email attachment passes antivirus scanning, but when executed, it decodes a Base64-encoded payload and establishes an outbound connection.'),

('T1562', 'Impair Defenses', 'Defense Evasion', 'TA0005', 'Intermediate',
 ARRAY['Blue Team', 'Purple Team'],
 'Attackers disable or tamper with security tools — antivirus, firewalls, logging agents — to blind defenders and operate without detection.',
 'Audit Failure',
 'When security tools go dark, attackers can operate freely. Alert fatigue from false positives is often exploited to normalize the silence before a major incident.',
 'If an attacker can turn off our alarms before committing the crime, everything else becomes easier. Monitoring the health of our security tools is just as important as the tools themselves.',
 '[{"industry":"Financial Services","description":"Antivirus service terminated on trading workstations before a credential dumping attack."},{"industry":"Healthcare","description":"Logging agent disabled on a hospital server hours before a ransomware deployment."}]',
 ARRAY['Security tool heartbeat monitoring','Alerts on AV/EDR service stop events','SIEM gap detection for missing log sources'],
 ARRAY['Protect security tool processes from termination','Tamper protection on endpoint agents','Out-of-band monitoring for tool health'],
 'How should organizations detect when their own security tools have been disabled or tampered with?',
 'The EDR console shows a workstation went offline 4 hours ago. The endpoint''s AV service was manually stopped by a process running as SYSTEM.'),

('T1218', 'System Binary Proxy Execution', 'Defense Evasion', 'TA0005', 'Intermediate',
 ARRAY['Red Team', 'Blue Team'],
 'Attackers use trusted, signed Windows binaries like mshta.exe, regsvr32.exe, or certutil.exe to execute malicious code — bypassing application control policies.',
 'Business Interruption',
 'Legitimate signed binaries trusted by the OS are weaponized to run attacker code. Application allowlisting that only checks signatures is bypassed entirely.',
 'Attackers turn our own trusted operating system tools against us. A signed Microsoft binary executing attacker code defeats most traditional allowlisting controls.',
 '[{"industry":"Technology","description":"certutil.exe used to download and decode a malicious payload disguised as a certificate file."},{"industry":"Government","description":"mshta.exe executing a remote HTA file containing an attacker''s backdoor from a signed process."}]',
 ARRAY['Command-line argument monitoring for LOLBin abuse','Child process monitoring for unusual binaries','Script block logging for HTA and WSH execution'],
 ARRAY['Application control with behavioral rules','Monitor and restrict LOLBin usage','Attack surface reduction rules in Windows Defender'],
 'Why does signing a binary with a trusted certificate not guarantee it cannot be weaponized?',
 'certutil.exe runs on a workstation and downloads a file from an external URL, decodes it from Base64, and saves it to a temp folder — all legitimate certutil functionality.'),

-- ── CREDENTIAL ACCESS ────────────────────────────────────────
('T1003', 'OS Credential Dumping', 'Credential Access', 'TA0006', 'Intermediate',
 ARRAY['Red Team', 'Purple Team'],
 'Attackers extract stored credentials (password hashes, tokens, tickets) from operating system memory or files to authenticate as legitimate users.',
 'Direct Financial Loss',
 'Dumped credentials give attackers the keys to move laterally, access sensitive data, and impersonate privileged users — dramatically increasing breach costs.',
 'When attackers steal credentials from memory, they can log in as our admins. This is why privileged access management and credential hygiene are critical investments.',
 '[{"industry":"Financial Services","description":"Dumped domain admin credentials used to access core banking and wire transfer systems."},{"industry":"Government","description":"Credential extraction from classified workstations enabling lateral movement to high-value intelligence systems."}]',
 ARRAY['LSASS memory access alerts','Credential Guard status monitoring','Honeypot credential detection'],
 ARRAY['Windows Credential Guard','Privileged access workstations (PAWs)','Restrict debug privileges'],
 'Why do attackers target LSASS memory specifically, and how does Credential Guard mitigate this?',
 'An EDR alert shows a process (not an admin tool) attempting to read the memory of lsass.exe on a domain controller.'),

('T1110', 'Brute Force', 'Credential Access', 'TA0006', 'Beginner',
 ARRAY['Blue Team', 'GRC Focus'],
 'Attackers systematically try many passwords or credential combinations to guess the correct one and gain access to accounts.',
 'Regulatory Action',
 'Successful brute force attacks often indicate weak password policies, which regulators view as a fundamental control failure.',
 'If our accounts can be guessed through repeated login attempts, we have a password policy problem. Account lockout and MFA are the minimum standard regulators expect.',
 '[{"industry":"Healthcare","description":"Brute-forced clinician accounts providing access to patient records and prescription systems."},{"industry":"Retail","description":"Credential stuffing attacks on customer loyalty accounts leading to points theft and data exposure."}]',
 ARRAY['Failed login threshold alerts','Password spray detection across multiple accounts','Geo-impossible travel alerts'],
 ARRAY['Multi-factor authentication','Account lockout policies','Password complexity requirements and breach-password screening'],
 'What is the difference between brute force, password spraying, and credential stuffing?',
 'The SIEM shows 500 failed login attempts against the VPN portal in 10 minutes, each using a different username but the same password.'),

('T1056', 'Input Capture', 'Credential Access', 'TA0006', 'Intermediate',
 ARRAY['Blue Team', 'Red Team'],
 'Attackers capture keystrokes, clipboard content, or form input to steal credentials and sensitive data as users type them.',
 'Direct Financial Loss',
 'Keyloggers capture credentials at the source — before encryption, before MFA prompts — making them one of the most direct paths to account compromise.',
 'A keylogger captures every password an employee types, including MFA codes. Traditional network security tools cannot stop data that is captured before it is ever sent anywhere.',
 '[{"industry":"Financial Services","description":"Keylogger on a trader''s workstation capturing banking credentials and MFA codes in real time."},{"industry":"Healthcare","description":"Input capture malware recording clinician EHR login credentials across a hospital network."}]',
 ARRAY['Behavioral detection of keylogging APIs','Clipboard monitoring anomalies','Endpoint memory scanning for keylogger patterns'],
 ARRAY['Endpoint detection and response','Hardware security keys (FIDO2) resistant to keylogging','Privileged access workstations with no internet access'],
 'Why are hardware security keys (FIDO2) more resistant to keylogging than software MFA?',
 'An EDR alert shows a process hooking the SetWindowsHookEx API — the standard mechanism used by keyloggers to capture all keyboard input system-wide.'),

('T1555', 'Credentials from Password Stores', 'Credential Access', 'TA0006', 'Intermediate',
 ARRAY['Red Team', 'Blue Team'],
 'Attackers extract saved passwords from browsers, password managers, or OS credential stores — gathering credentials the user saved for convenience.',
 'Direct Financial Loss',
 'Saved browser passwords are a gold mine for attackers. One compromised endpoint can yield dozens of credentials across personal and corporate accounts.',
 'Most employees save passwords in their browser for convenience. When an attacker accesses a workstation, those saved credentials are immediately available — no cracking required.',
 '[{"industry":"Retail","description":"Browser credential extraction from a point-of-sale system yielding e-commerce and banking credentials."},{"industry":"Technology","description":"Developer workstation compromise exposing saved API keys, cloud console credentials, and code repository tokens."}]',
 ARRAY['Process access monitoring for browser credential stores','Endpoint detection for credential extraction tools','Browser extension auditing'],
 ARRAY['Enterprise password manager with no browser save','Endpoint protection with credential theft detection','Privileged workstation policies prohibiting general browsing'],
 'Why are browser-saved passwords a higher risk than people generally assume?',
 'An attacker runs a tool that extracts all Chrome saved passwords in under 30 seconds from an unlocked workstation — no administrative privileges required.'),

-- ── DISCOVERY ───────────────────────────────────────────────
('T1087', 'Account Discovery', 'Discovery', 'TA0007', 'Beginner',
 ARRAY['Red Team', 'Blue Team'],
 'Attackers enumerate user accounts on local systems, domains, or cloud environments to identify high-value targets for further exploitation.',
 'Loss of Confidence',
 'Account enumeration reveals the organizational structure and identifies privileged accounts, providing attackers a roadmap for escalation.',
 'Attackers map out our user accounts to find admin and executive targets. Monitoring for unusual account queries helps us catch intruders during the reconnaissance phase.',
 '[{"industry":"Technology","description":"Enumeration of cloud IAM roles identifying service accounts with overprivileged access."},{"industry":"Financial Services","description":"Discovery of privileged trading system accounts for targeted credential attacks."}]',
 ARRAY['Unusual LDAP queries from non-admin workstations','Cloud API calls listing IAM users','Net user / net group command monitoring'],
 ARRAY['Restrict LDAP query access','Monitor cloud IAM API usage','Limit account visibility through tiered administration'],
 'Why is account discovery a critical step for attackers before lateral movement?',
 'A workstation in the marketing department is running "net group Domain Admins /domain" commands during business hours.'),

('T1046', 'Network Service Scanning', 'Discovery', 'TA0007', 'Beginner',
 ARRAY['Red Team', 'Blue Team'],
 'Attackers scan the internal network to discover available services, open ports, and potential targets for lateral movement.',
 'Business Interruption',
 'Internal scanning provides attackers a map of the network, revealing vulnerable services and pathways to critical systems.',
 'Once inside our network, attackers scan for open doors — unpatched services, exposed databases, management interfaces. Network segmentation limits what they can find.',
 '[{"industry":"Manufacturing","description":"Scanning revealing exposed SCADA and ICS systems on flat network segments."},{"industry":"Healthcare","description":"Discovery of unsegmented medical devices with known vulnerabilities."}]',
 ARRAY['Internal network scan detection (port sweep alerts)','Anomalous connection volume from single host','IDS/IPS signature for scanning tools'],
 ARRAY['Network segmentation and microsegmentation','Host-based firewalls','Intrusion detection systems on internal segments'],
 'How does network segmentation reduce the value of internal network scanning for an attacker?',
 'Network monitoring shows a single workstation attempting connections to port 445 on every IP address in the 10.0.0.0/16 subnet within 5 minutes.'),

('T1082', 'System Information Discovery', 'Discovery', 'TA0007', 'Beginner',
 ARRAY['Red Team', 'Blue Team'],
 'Attackers gather detailed information about the compromised system — OS version, hardware, installed software, network configuration — to plan their next moves.',
 'Loss of Confidence',
 'System enumeration tells attackers exactly what they are working with — what patches are missing, what security tools are installed, and what the network looks like from the inside.',
 'An attacker''s first move after getting in is to look around. System discovery commands run within minutes of a breach. Monitoring these commands is an early warning system.',
 '[{"industry":"Technology","description":"Automated discovery scripts enumerating cloud instance metadata, environment variables, and IAM roles."},{"industry":"Healthcare","description":"Medical device OS enumeration revealing end-of-life operating systems without security support."}]',
 ARRAY['Command-line monitoring for systeminfo, uname, hostname','Process execution analytics for discovery tool chains','Endpoint detection for enumeration script patterns'],
 ARRAY['Disable or restrict system information commands for standard users','Monitor and baseline discovery command usage','EDR behavioral detection for post-compromise discovery'],
 'What does an attacker learn from running "systeminfo" that makes it worth the detection risk?',
 'Within 10 minutes of a phishing email being opened, the affected endpoint runs systeminfo, ipconfig /all, net localgroup administrators, and whoami in rapid succession.'),

('T1057', 'Process Discovery', 'Discovery', 'TA0007', 'Beginner',
 ARRAY['Red Team', 'Blue Team'],
 'Attackers list running processes on a compromised system to identify security tools to avoid, high-value applications to target, and the overall security posture.',
 'Loss of Confidence',
 'By listing running processes, attackers immediately know which security tools are active and which applications hold sensitive data worth targeting.',
 'An attacker who knows our security tools can work around them. Process discovery gives attackers a real-time inventory of our defenses — and our valuable targets.',
 '[{"industry":"Financial Services","description":"Process listing revealing active trading platform processes to target for credential interception."},{"industry":"Technology","description":"Security tool discovery enabling attackers to adjust techniques to avoid specific EDR detection."}]',
 ARRAY['Behavioral detection of process enumeration commands (tasklist, ps)','Honey processes — fake security tool processes that alert when queried','Process access monitoring'],
 ARRAY['Deploy decoy security tool processes as honeypots','EDR with process enumeration detection','Limit access to process listing for standard user accounts'],
 'How can organizations use the attacker''s need to enumerate processes as a detection opportunity?',
 'A compromised endpoint runs tasklist.exe and the output is sent to a remote server. The process list reveals which EDR product is installed.'),

-- ── LATERAL MOVEMENT ────────────────────────────────────────
('T1021', 'Remote Services', 'Lateral Movement', 'TA0008', 'Intermediate',
 ARRAY['Red Team', 'Blue Team'],
 'Attackers use legitimate remote access services like RDP, SSH, or SMB to move between systems using stolen credentials.',
 'Direct Financial Loss',
 'Lateral movement through remote services allows attackers to reach high-value targets like financial systems, databases, and domain controllers.',
 'Attackers use the same remote access tools our IT staff relies on. Without proper segmentation and monitoring, they can reach any system in the network.',
 '[{"industry":"Financial Services","description":"RDP lateral movement from a compromised workstation to payment processing servers."},{"industry":"Government","description":"SSH pivoting across segmented networks to reach classified information systems."}]',
 ARRAY['Unusual RDP/SSH sessions from non-admin endpoints','Lateral movement analytics in EDR','Authentication anomaly detection'],
 ARRAY['Network segmentation','Restrict remote service access to jump servers','Privileged access management'],
 'Why should organizations use jump servers instead of allowing direct RDP/SSH between all systems?',
 'A workstation in accounting establishes an RDP session to a database server at 11 PM. The account used has never accessed that server before.'),

('T1550', 'Use Alternate Authentication Material', 'Lateral Movement', 'TA0008', 'Advanced',
 ARRAY['Red Team', 'Purple Team'],
 'Attackers use stolen password hashes, Kerberos tickets, or tokens instead of plaintext passwords to authenticate and move laterally.',
 'Loss of Confidence',
 'Pass-the-hash and pass-the-ticket attacks bypass traditional authentication logging, making attacker movement invisible to standard monitoring.',
 'Attackers do not need to know passwords — stolen authentication tokens let them impersonate any user. This makes strong credential isolation and monitoring essential.',
 '[{"industry":"Financial Services","description":"Golden ticket attacks granting persistent, undetectable access to the entire Active Directory domain."},{"industry":"Technology","description":"Stolen OAuth tokens providing access to cloud services and SaaS applications without triggering MFA."}]',
 ARRAY['Kerberos anomaly detection (overpass-the-hash)','Token replay detection','Impossible travel for authentication events'],
 ARRAY['Credential Guard','Regular KRBTGT password rotation','Tiered administration model'],
 'What is the difference between pass-the-hash, pass-the-ticket, and golden ticket attacks?',
 'A Kerberos ticket for a domain admin account has a 10-year expiration. Normal tickets in this environment expire after 10 hours.'),

('T1534', 'Internal Spearphishing', 'Lateral Movement', 'TA0008', 'Intermediate',
 ARRAY['Blue Team', 'GRC Focus'],
 'Attackers use a compromised internal account to send phishing emails to colleagues — the message comes from a trusted coworker, making it far more convincing.',
 'Direct Financial Loss',
 'An internal phishing email from a known colleague bypasses email gateway controls and carries enormous social trust — the recipient has no reason to be suspicious.',
 'Once attackers have one mailbox, they weaponize it against everyone in the contact list. Internal phishing has a dramatically higher success rate than external campaigns.',
 '[{"industry":"Financial Services","description":"Compromised CFO email used to send wire transfer requests to the finance team — approved because the sender is trusted."},{"industry":"Technology","description":"Compromised developer account sending malicious code review links to the entire engineering department."}]',
 ARRAY['Unusual internal email sending volume','Links in internal email pointing to external domains','User-reported suspicious internal emails'],
 ARRAY['Email DLP for internal messages','Zero-trust verification for financial requests regardless of sender','Security awareness training covering internal phishing'],
 'Why is an internal phishing email significantly more dangerous than an external one?',
 'The CFO''s assistant receives an email from the CFO''s actual account asking her to urgently wire $75,000 to a new vendor. The CFO''s account was compromised 48 hours earlier.'),

-- ── COLLECTION ───────────────────────────────────────────────
('T1114', 'Email Collection', 'Collection', 'TA0009', 'Intermediate',
 ARRAY['Blue Team', 'GRC Focus'],
 'Attackers access email accounts or servers to collect sensitive communications, contacts, attachments, and organizational intelligence.',
 'Legal Liability',
 'Email collections can expose attorney-client privilege, trade secrets, M&A plans, and regulated personal data — creating significant legal and regulatory exposure.',
 'Our email contains our most sensitive communications — legal strategy, financial plans, customer data. When attackers access mailboxes, the exposure is both legal and reputational.',
 '[{"industry":"Financial Services","description":"Access to executive mailboxes revealing upcoming M&A activity, enabling insider trading."},{"industry":"Government","description":"Collection of diplomatic communications for intelligence purposes."}]',
 ARRAY['Unusual mailbox access patterns (volume, time, location)','Email forwarding rule creation alerts','eDiscovery / compliance search monitoring'],
 ARRAY['Mailbox access auditing','Conditional access policies','Data loss prevention for email'],
 'Why is email one of the highest-value targets for both espionage and financial crime?',
 'A new inbox rule is created on the CFO''s mailbox forwarding all emails containing "merger," "acquisition," or "confidential" to an external Gmail address.'),

('T1113', 'Screen Capture', 'Collection', 'TA0009', 'Beginner',
 ARRAY['Blue Team', 'Red Team'],
 'Attackers take screenshots of the victim''s desktop to capture displayed information such as documents, credentials, or sensitive applications.',
 'Loss of Confidence',
 'Screen captures can expose any information visible on screen, including data not stored in files — such as dashboards, messages, and live transactions.',
 'Attackers can silently photograph everything on an employee''s screen. This captures data that never gets saved to a file — trading screens, chat messages, client information.',
 '[{"industry":"Financial Services","description":"Screenshots of trading terminals capturing position data and order flow."},{"industry":"Healthcare","description":"Screen captures of patient charts during clinical review."}]',
 ARRAY['API calls to screen capture functions','Unusual image files in temp directories','EDR behavior analytics for screenshot tools'],
 ARRAY['Endpoint detection for screen capture APIs','Desktop watermarking','Application-level screen capture prevention'],
 'Why is screen capture particularly dangerous for organizations that handle sensitive visual data?',
 'An EDR alert shows a process repeatedly calling the Windows GDI screen capture API every 30 seconds and saving JPG files to a hidden temp folder.'),

('T1005', 'Data from Local System', 'Collection', 'TA0009', 'Beginner',
 ARRAY['Blue Team', 'Red Team'],
 'Attackers search through local files, folders, and drives on a compromised system to find sensitive data worth exfiltrating.',
 'Legal Liability',
 'A compromised endpoint often contains far more sensitive data than attackers expected — documents, credentials, configuration files, and cached data from cloud services.',
 'Every employee laptop is a potential data breach waiting to happen. Local data discovery is how attackers turn a single compromised workstation into a major data incident.',
 '[{"industry":"Technology","description":"Source code, API keys, and credentials found in developer home directories and desktop files."},{"industry":"Healthcare","description":"PHI-containing spreadsheets found on clinician laptops outside the approved data governance system."}]',
 ARRAY['Unusual file access patterns (breadth and volume)','DLP alerts on sensitive file type access','EDR behavioral detection for data staging activity'],
 ARRAY['Data loss prevention (DLP)','Enforce data classification and storage policies','Endpoint encryption for sensitive data at rest'],
 'What types of data are most commonly found on endpoints that organizations did not realize were there?',
 'A compromised workstation runs a script that searches for *.xlsx, *.pdf, and *.docx files containing keywords like "password," "SSN," and "confidential" and copies them to a zip file.'),

('T1560', 'Archive Collected Data', 'Collection', 'TA0009', 'Intermediate',
 ARRAY['Blue Team', 'Red Team'],
 'Attackers compress or encrypt collected files before exfiltration to reduce size, avoid DLP detection, and make the contents unreadable in transit.',
 'Regulatory Action',
 'Encrypted archives bypass content-based DLP tools — the sensitive data is hidden inside a zip or 7z file that looks like noise on the wire.',
 'Data loss prevention tools that scan content cannot read inside encrypted archives. Attackers use this to package stolen data in a way that defeats our controls at the perimeter.',
 '[{"industry":"Financial Services","description":"Customer records compressed and password-protected before upload to a cloud service, bypassing DLP."},{"industry":"Healthcare","description":"PHI data packaged into encrypted archives to evade email content scanning before exfiltration."}]',
 ARRAY['Archive file creation monitoring (zip, 7z, rar) at unusual volume','DLP alerts on archive uploads to cloud services','Endpoint behavioral detection for data staging patterns'],
 ARRAY['Network DLP with archive inspection capability','Endpoint DLP monitoring file staging behavior','Data egress controls on cloud upload destinations'],
 'Why does encryption of collected data fundamentally challenge content-based DLP approaches?',
 'A compromised workstation creates a 2GB password-protected zip file in the AppData folder containing hundreds of documents, then uploads it to a file-sharing service.'),

-- ── COMMAND AND CONTROL ─────────────────────────────────────
('T1071', 'Application Layer Protocol', 'Command and Control', 'TA0011', 'Intermediate',
 ARRAY['Blue Team', 'Purple Team'],
 'Attackers communicate with compromised systems using standard protocols like HTTPS, DNS, or SMTP to blend C2 traffic with normal network activity.',
 'Business Interruption',
 'C2 over standard protocols evades basic network monitoring, allowing attackers to maintain persistent control and coordinate operations undetected.',
 'Attackers hide their communications inside normal web traffic. Without deep inspection of outbound connections, we cannot distinguish attacker commands from employee browsing.',
 '[{"industry":"Government","description":"DNS-based C2 channels bypassing air-gapped network inspection for long-term espionage."},{"industry":"Manufacturing","description":"HTTPS-based C2 blending with legitimate cloud service traffic on OT networks."}]',
 ARRAY['DNS query anomaly detection (length, frequency, entropy)','JA3/JA3S TLS fingerprinting','Beaconing pattern detection'],
 ARRAY['DNS filtering and monitoring','TLS inspection','Network detection and response (NDR)'],
 'Why is DNS particularly attractive as a C2 channel for attackers?',
 'A workstation generates 10,000 DNS queries per hour to unique subdomains of a single domain. Each subdomain appears to contain encoded data.'),

('T1573', 'Encrypted Channel', 'Command and Control', 'TA0011', 'Advanced',
 ARRAY['Blue Team', 'Red Team'],
 'Attackers encrypt their command-and-control communications to prevent network security tools from inspecting the content of their traffic.',
 'Business Interruption',
 'Encrypted C2 channels render content-based network inspection useless, allowing attackers to operate freely unless metadata-based detection is in place.',
 'Attackers encrypt their traffic just like we encrypt ours. Without the ability to inspect encrypted outbound connections, our network security tools are blind.',
 '[{"industry":"Financial Services","description":"Custom-encrypted channels evading DLP and network monitoring on trading networks."},{"industry":"Government","description":"State-sponsored actors using proprietary encryption to bypass national monitoring infrastructure."}]',
 ARRAY['TLS certificate anomalies (self-signed, short-lived)','JA3 hash matching against known malware profiles','Encrypted traffic metadata analysis'],
 ARRAY['TLS inspection at network boundary','Certificate allowlisting','Endpoint-based C2 detection (EDR)'],
 'How can organizations detect malicious encrypted traffic without decrypting everything?',
 'A workstation establishes a TLS connection to an IP address with a self-signed certificate. The JA3 fingerprint matches a known Cobalt Strike beacon profile.'),

('T1572', 'Protocol Tunneling', 'Command and Control', 'TA0011', 'Advanced',
 ARRAY['Blue Team', 'Purple Team'],
 'Attackers tunnel malicious traffic inside legitimate protocols — for example, hiding C2 commands inside DNS queries or HTTP requests — to bypass protocol-based firewalls.',
 'Business Interruption',
 'Protocol tunneling defeats firewall rules that allow specific protocols. DNS is almost always allowed outbound — making it a universal smuggling channel.',
 'If attackers can hide their commands inside DNS queries, they can communicate with compromised systems even through the most restrictive firewalls. Protocol intent, not just protocol type, must be inspected.',
 '[{"industry":"Government","description":"DNS tunneling carrying C2 traffic through a firewall that only blocks non-standard protocols."},{"industry":"Financial Services","description":"HTTP tunneling encoding C2 commands in normal-looking web request headers."}]',
 ARRAY['DNS query volume and entropy analysis','Deep packet inspection for protocol anomalies','Network detection for tunneling tool signatures (iodine, dnscat2)'],
 ARRAY['DNS filtering with query analytics','Deep packet inspection beyond protocol type','Network detection and response (NDR) with behavioral analytics'],
 'Why is DNS tunneling particularly difficult to block without impacting legitimate DNS traffic?',
 'DNS logs show queries to subdomains like "aGVsbG8gd29ybGQ.attacker.com" — the subdomain is Base64-encoded data, not a real hostname.'),

-- ── EXFILTRATION ─────────────────────────────────────────────
('T1041', 'Exfiltration Over C2 Channel', 'Exfiltration', 'TA0010', 'Intermediate',
 ARRAY['Blue Team', 'Purple Team'],
 'Attackers steal data by sending it out through the same command-and-control connection they use to control the compromised system.',
 'Regulatory Action',
 'Data exfiltration over existing C2 channels is harder to detect because it blends with the attacker''s normal communication, delaying breach discovery and notification.',
 'Attackers can steal our data through the same hidden channel they use to control compromised machines. Without network monitoring for unusual outbound traffic, we may never know data left.',
 '[{"industry":"Healthcare","description":"Patient records exfiltrated over encrypted C2 channel, delaying HIPAA breach notification timeline."},{"industry":"Retail","description":"Payment card data exfiltrated in small batches to avoid detection thresholds."}]',
 ARRAY['Unusual outbound data volume per endpoint','Beaconing detection (periodic outbound connections)','DNS tunneling detection'],
 ARRAY['Network DLP','Egress filtering','TLS inspection for outbound traffic'],
 'Why does combining C2 and exfiltration into one channel make detection more difficult?',
 'Network monitoring shows a workstation sending 2 GB of data to a cloud service IP over HTTPS at 2 AM on a weekend. Normal daily upload volume for this host is under 50 MB.'),

('T1567', 'Exfiltration Over Web Service', 'Exfiltration', 'TA0010', 'Intermediate',
 ARRAY['Blue Team', 'GRC Focus'],
 'Attackers upload stolen data to legitimate cloud services like Google Drive, Dropbox, or Pastebin to blend exfiltration with normal business traffic.',
 'Regulatory Action',
 'Using legitimate cloud services for exfiltration makes stolen data nearly invisible in network logs, delaying detection and breach response.',
 'Attackers upload our data to the same cloud services we use every day — Google Drive, OneDrive, Dropbox. Without cloud access controls, data walks out the front door.',
 '[{"industry":"Technology","description":"Source code uploaded to personal cloud storage accounts by compromised developer workstations."},{"industry":"Financial Services","description":"Customer account data exfiltrated to file-sharing services, triggering PCI DSS and privacy violations."}]',
 ARRAY['Cloud access security broker (CASB) monitoring','Unusual upload volume to cloud storage','DLP policy triggers on sensitive file patterns'],
 ARRAY['CASB deployment','Restrict personal cloud storage access','Endpoint DLP'],
 'How does the use of legitimate cloud services for exfiltration challenge traditional network security controls?',
 'A finance department laptop uploads 500 MB to a personal Dropbox account. The organization uses OneDrive as its approved cloud storage.'),

('T1048', 'Exfiltration Over Alternative Protocol', 'Exfiltration', 'TA0010', 'Advanced',
 ARRAY['Blue Team', 'Purple Team'],
 'Attackers use non-standard protocols like FTP, SFTP, DNS, ICMP, or custom protocols to exfiltrate data and bypass controls that focus on HTTP/HTTPS.',
 'Regulatory Action',
 'Exfiltration over unexpected protocols bypasses DLP tools and firewall rules that only inspect common web traffic, allowing data to leave undetected.',
 'Most data loss prevention tools focus on web traffic. Attackers exfiltrate through DNS, ICMP, or FTP — protocols that security teams often overlook — and the data walks right out.',
 '[{"industry":"Government","description":"ICMP tunneling used to exfiltrate classified data through a firewall that only inspects TCP/UDP traffic."},{"industry":"Financial Services","description":"FTP exfiltration of customer data to an overseas server through a firewall policy gap."}]',
 ARRAY['Protocol anomaly detection on egress traffic','DNS exfiltration detection (query size, frequency, entropy)','ICMP traffic volume monitoring'],
 ARRAY['Egress filtering restricting unnecessary outbound protocols','Network detection and response (NDR)','Full packet capture for incident investigation'],
 'Why do organizations often have weaker controls on DNS and ICMP compared to HTTP/HTTPS?',
 'Network monitoring shows large ICMP packets leaving the network at regular 30-second intervals — ICMP is not blocked outbound and is being used to carry encoded data.'),

-- ── IMPACT ───────────────────────────────────────────────────
('T1486', 'Data Encrypted for Impact', 'Impact', 'TA0012', 'Beginner',
 ARRAY['Blue Team', 'GRC Focus'],
 'Attackers encrypt files and systems with ransomware, making data inaccessible until a ransom is paid or backups are restored.',
 'Direct Financial Loss',
 'Ransomware can halt all business operations, destroy data, and result in ransom payments, recovery costs, regulatory fines, and customer lawsuits.',
 'Ransomware is the most financially devastating cyberattack most organizations face. Tested backups and incident response plans are our insurance policy against total operational shutdown.',
 '[{"industry":"Healthcare","description":"Hospital systems encrypted, forcing diversion of emergency patients and cancellation of surgeries."},{"industry":"Manufacturing","description":"Production lines shut down for weeks while systems are rebuilt from backups."},{"industry":"Government","description":"City and county services offline, disrupting 911 dispatch, court systems, and public records."}]',
 ARRAY['Mass file rename or extension change alerts','Canary file monitoring (honeypot files)','Volume shadow copy deletion detection'],
 ARRAY['Immutable offline backups','Network segmentation','Endpoint detection with ransomware-specific behavioral rules'],
 'Why are tested, offline backups the single most important defense against ransomware?',
 'At 5 AM, a file server begins renaming thousands of files with a .locked extension. The volume shadow copies are deleted simultaneously.'),

('T1498', 'Network Denial of Service', 'Impact', 'TA0012', 'Beginner',
 ARRAY['Blue Team', 'GRC Focus'],
 'Attackers flood network resources with traffic to overwhelm systems and make services unavailable to legitimate users.',
 'Business Interruption',
 'DDoS attacks can take customer-facing services offline for hours or days, causing revenue loss and reputational damage.',
 'A DDoS attack can take our website and services offline in minutes. DDoS mitigation services are a cost of doing business for any organization with an internet presence.',
 '[{"industry":"Financial Services","description":"Online banking and trading platforms taken offline during critical market hours."},{"industry":"Retail","description":"E-commerce sites unavailable during peak shopping periods, causing direct revenue loss."}]',
 ARRAY['Traffic volume anomaly detection','CDN and ISP-level DDoS alerts','Application response time degradation'],
 ARRAY['DDoS mitigation services (CDN-based)','Rate limiting','Anycast network distribution'],
 'What is the difference between volumetric, protocol, and application-layer DDoS attacks?',
 'The company website response time jumps from 200ms to 30 seconds. Network monitoring shows a 50x increase in inbound traffic from thousands of source IPs.'),

('T1485', 'Data Destruction', 'Impact', 'TA0012', 'Intermediate',
 ARRAY['Blue Team', 'Purple Team'],
 'Attackers deliberately destroy data, databases, or entire systems to cause maximum disruption and deny the organization access to its own information.',
 'Direct Financial Loss',
 'Intentional data destruction can permanently eliminate business records, intellectual property, and operational data — with recovery costs reaching millions.',
 'Unlike ransomware where data can potentially be recovered, data destruction is permanent. Our backup and disaster recovery capabilities directly determine how fast we can resume operations.',
 '[{"industry":"Financial Services","description":"Destruction of transaction records requiring costly manual reconstruction and regulatory reporting."},{"industry":"Government","description":"Wiper malware destroying agency databases and citizen records as part of geopolitical conflict."}]',
 ARRAY['Mass file deletion alerts','Disk wipe tool execution detection','Database drop/truncate command monitoring'],
 ARRAY['Immutable backup storage','Disaster recovery testing','Least privilege on database and file server access'],
 'How does a wiper attack differ from ransomware in terms of attacker motivation and organizational recovery?',
 'A compromised admin account executes a script that truncates all tables in the production database and then wipes the backup server.'),

('T1491', 'Defacement', 'Impact', 'TA0012', 'Beginner',
 ARRAY['Blue Team', 'GRC Focus'],
 'Attackers modify the visual content of websites or internal systems to display their own messaging — for political statements, reputation damage, or to signal a successful breach.',
 'Loss of Confidence',
 'Website defacement is one of the most visible and embarrassing cyberattacks. Even if systems are restored quickly, the reputational damage and customer confidence impact can be severe.',
 'A defaced website tells the world we were breached before our communications team can respond. Reputational recovery from a public defacement takes far longer than technical recovery.',
 '[{"industry":"Government","description":"Government agency website defaced with political messaging, triggering media coverage and public concern."},{"industry":"Retail","description":"E-commerce homepage replaced with attacker content, driving customers to competitors and triggering stock impact."}]',
 ARRAY['File integrity monitoring on web content directories','Web application change detection','CDN purge event monitoring'],
 ARRAY['File integrity monitoring on web servers','Web application firewall','Immutable web content deployment pipelines'],
 'Why is website defacement often a sign of a deeper, more serious compromise than it appears?',
 'The company''s public website is replaced with a hacktivist message at 8 AM. Customer service is flooded with calls before the security team is notified.'),

('T1489', 'Service Stop', 'Impact', 'TA0012', 'Intermediate',
 ARRAY['Blue Team', 'Purple Team'],
 'Attackers stop critical services — backup agents, security tools, databases — to maximize the impact of their attack and prevent recovery.',
 'Business Interruption',
 'Stopping backup and security services before deploying ransomware or wipers ensures maximum damage and minimum recovery options.',
 'Ransomware operators systematically disable backup services before encrypting data. If our backups stop running and nobody notices, our recovery options disappear before the attack even begins.',
 '[{"industry":"Healthcare","description":"Backup services stopped on hospital servers before ransomware deployment, eliminating recovery options."},{"industry":"Manufacturing","description":"Database services halted on production systems, shutting down manufacturing operations."}]',
 ARRAY['Service stop events for critical processes (Event ID 7036)','Backup agent health monitoring','Security tool service monitoring'],
 ARRAY['Protect critical service processes from termination','Out-of-band backup health monitoring','Tamper protection on security tools'],
 'Why do ransomware operators prioritize stopping backup services before deploying their payload?',
 'The backup agent service on all file servers stops within a 10-minute window on a Sunday night. Three hours later, ransomware begins encrypting files.'),

-- ── ADDITIONAL HIGH-VALUE TECHNIQUES ────────────────────────
('T1566.002', 'Phishing: Spearphishing Link', 'Initial Access', 'TA0001', 'Intermediate',
 ARRAY['Blue Team', 'GRC Focus'],
 'Attackers send targeted phishing emails containing a malicious link crafted specifically for the recipient — using personal details to make the message convincing.',
 'Direct Financial Loss',
 'Spearphishing has a significantly higher success rate than generic phishing because it is personalized — the attacker has done research and the email feels legitimate.',
 'When attackers know a target''s name, role, projects, and manager, their phishing emails are nearly indistinguishable from real communications. Generic defenses are insufficient.',
 '[{"industry":"Financial Services","description":"Targeted executive phishing referencing real deal names and counterparties to steal M&A credentials."},{"industry":"Technology","description":"Developer-targeted phishing impersonating GitHub notifications for code review links."}]',
 ARRAY['URL click-time protection and sandboxing','User-reported phishing pipeline','Threat intelligence correlation on phishing domains'],
 ARRAY['Security awareness training with spearphishing simulations','Multi-factor authentication','Email authentication enforcement'],
 'What reconnaissance do attackers typically conduct before launching a spearphishing campaign?',
 'A sales executive receives an email referencing her real customer by name, her real colleague as the sender, and a link to "updated contract terms" — all details available on LinkedIn.'),

('T1499', 'Endpoint Denial of Service', 'Impact', 'TA0012', 'Intermediate',
 ARRAY['Blue Team', 'GRC Focus'],
 'Attackers target individual endpoints or applications with resource exhaustion to make them crash or become unresponsive, disrupting specific services.',
 'Business Interruption',
 'Application-layer denial of service can be launched with minimal traffic by targeting specific application vulnerabilities, making it harder to detect than volumetric attacks.',
 'Application-layer DoS attacks target specific features of our applications, not just the network. A small number of carefully crafted requests can crash a server that handles millions of normal requests.',
 '[{"industry":"Financial Services","description":"Trading application endpoint targeted with resource-exhaustion requests during peak market hours."},{"industry":"Healthcare","description":"Electronic health record application made unresponsive during a critical care period."}]',
 ARRAY['Application performance monitoring anomaly detection','Rate limiting rule triggers','Error rate spikes in application logs'],
 ARRAY['Rate limiting and request validation','Web application firewall with behavioral rules','Horizontal scaling and load balancing'],
 'What is the difference between a network-layer DDoS attack and an application-layer DoS attack?',
 'A web application becomes unresponsive to legitimate users after receiving 500 requests per second — well below the network bandwidth limit — because each request triggers an expensive database query.'),

('T1110.003', 'Brute Force: Password Spraying', 'Credential Access', 'TA0006', 'Beginner',
 ARRAY['Blue Team', 'GRC Focus'],
 'Attackers try one or a few common passwords against many different accounts to avoid lockout policies — trading speed for stealth.',
 'Regulatory Action',
 'Password spraying evades lockout thresholds by staying under the failed-login limit on each account, making it nearly invisible to traditional account lockout monitoring.',
 'Password spraying finds the weakest password in the organization. All it takes is one account with "Winter2024!" and the attacker has a foothold. Password policy enforcement is non-negotiable.',
 '[{"industry":"Healthcare","description":"Staff accounts compromised through spraying with seasonal passwords, exposing patient data systems."},{"industry":"Financial Services","description":"Password spray against Microsoft 365 gaining access to executive email accounts."}]',
 ARRAY['Distributed failed login detection across multiple accounts','Baseline deviation alerts for login failure rates','Identity protection spray detection analytics'],
 ARRAY['Ban common passwords with breach-password screening','Multi-factor authentication on all accounts','Identity protection policies in Azure AD / Entra ID'],
 'Why does password spraying bypass traditional account lockout policies?',
 'Azure AD sign-in logs show 2 failed logins on each of 400 accounts within a 30-minute window — all using the same password. No single account hit the lockout threshold.'),

('T1036', 'Masquerading', 'Defense Evasion', 'TA0005', 'Beginner',
 ARRAY['Blue Team', 'Red Team'],
 'Attackers disguise malicious files, processes, or services as legitimate ones by giving them names similar to trusted system components or software.',
 'Business Interruption',
 'A process named "svchost32.exe" looks legitimate to a casual observer but is not a real Windows process. Detection requires knowing what legitimate looks like.',
 'Attackers rename their tools to look like normal Windows processes or user applications. Without verified process integrity, it is nearly impossible to separate attacker activity from legitimate operations.',
 '[{"industry":"Technology","description":"Malware renamed to "chrome_update.exe" placed in a temp folder and added to startup."},{"industry":"Financial Services","description":"Attacker''s C2 binary named "svchost.exe" running from a user''s AppData folder instead of System32."}]',
 ARRAY['Process path verification (svchost.exe should only run from System32)','File hash comparison against known-good baselines','Parent process anomaly detection'],
 ARRAY['Endpoint detection with process integrity verification','Application allowlisting based on path and hash','Alert on known-good process names running from unexpected paths'],
 'How can security teams efficiently distinguish legitimate system processes from masquerading malware?',
 'A process named "svchost.exe" is running from C:\\Users\\employee\\AppData\\Roaming\\ instead of C:\\Windows\\System32\\ — a classic masquerading technique.'),

('T1562.001', 'Impair Defenses: Disable or Modify Tools', 'Defense Evasion', 'TA0005', 'Intermediate',
 ARRAY['Blue Team', 'Purple Team'],
 'Attackers specifically target and disable security software — antivirus, EDR, firewalls — before conducting the main attack to operate without detection.',
 'Audit Failure',
 'Disabling security tools before attacking ensures the main event goes undetected. The silence in security logs is the warning sign that is most often missed.',
 'When our security tools go silent, it should immediately trigger an investigation. Attackers disable defenses first because they know the attack that follows will be logged.',
 '[{"industry":"Financial Services","description":"EDR agent killed on workstations hours before a mass credential dumping operation."},{"industry":"Healthcare","description":"Windows Defender disabled on hospital servers via registry modification before ransomware deployment."}]',
 ARRAY['Security tool heartbeat and health monitoring','Registry modification alerts for AV/EDR settings','Event log monitoring for security tool service stops'],
 ARRAY['Tamper protection on all endpoint security tools','Out-of-band monitoring that does not rely on the protected endpoint','Canary alerts when security tools go offline'],
 'Why is monitoring the health of your own security tools one of the most important detection capabilities?',
 'Windows Defender is disabled via registry modification on 50 endpoints within a 15-minute window. The EDR console shows those endpoints go dark. Ransomware begins 2 hours later.'),

('T1574', 'Hijack Execution Flow', 'Privilege Escalation', 'TA0004', 'Advanced',
 ARRAY['Red Team', 'Purple Team'],
 'Attackers manipulate how the OS or an application loads code — by planting malicious DLLs or modifying search paths — so their code runs in place of legitimate code.',
 'Business Interruption',
 'DLL hijacking runs attacker code inside a legitimate application''s process, inheriting its permissions and trust level. Detection requires knowing exactly what every application should load.',
 'Legitimate applications inadvertently become launchpads for attacker code. The application starts normally, but the malicious DLL it loads runs alongside it with full trust.',
 '[{"industry":"Technology","description":"Malicious DLL planted in an application directory runs with SYSTEM privileges when the application is started."},{"industry":"Government","description":"DLL search order hijacking on classified system software used to establish persistent privileged access."}]',
 ARRAY['DLL load monitoring for unexpected library paths','Process module integrity verification','File system monitoring of application directories'],
 ARRAY['Application manifest pinning of DLL load paths','Privileged path write protection','EDR with DLL load chain monitoring'],
 'Why do legitimate applications often have DLL search order vulnerabilities even when well-written?',
 'A legitimate signed application starts normally but loads a malicious DLL from the current working directory before finding the real DLL in System32.'),

('T1040', 'Network Sniffing', 'Credential Access', 'TA0006', 'Intermediate',
 ARRAY['Red Team', 'Blue Team'],
 'Attackers capture network traffic passing through a compromised system to harvest credentials, session tokens, and sensitive data transmitted in cleartext.',
 'Direct Financial Loss',
 'Any unencrypted protocol is vulnerable to sniffing. Legacy protocols like HTTP, FTP, Telnet, and SNMP v1/v2 transmit credentials and data in cleartext that any attacker on the network can read.',
 'Unencrypted protocols on our internal network are a vulnerability we often forget about. An attacker with access to one system can harvest credentials from the entire network segment.',
 '[{"industry":"Manufacturing","description":"Cleartext SCADA protocol credentials captured from industrial network traffic, enabling ICS manipulation."},{"industry":"Financial Services","description":"Unencrypted SNMP community strings captured, granting management access to network infrastructure."}]',
 ARRAY['Promiscuous mode network interface detection','Unexpected packet capture tool execution','Network anomaly detection for broadcast/ARP behavior'],
 ARRAY['Enforce encryption for all internal protocols','Network segmentation to limit broadcast domain scope','Detect and eliminate cleartext credential protocols'],
 'Which commonly used internal protocols still transmit credentials in cleartext that organizations should prioritize eliminating?',
 'A compromised workstation is running Wireshark in promiscuous mode, capturing all traffic on the network segment including cleartext LDAP queries with bind credentials.'),

('T1187', 'Forced Authentication', 'Credential Access', 'TA0006', 'Intermediate',
 ARRAY['Red Team', 'Blue Team'],
 'Attackers trick Windows systems into automatically authenticating to an attacker-controlled server, capturing the resulting NTLM hash for offline cracking or relay attacks.',
 'Direct Financial Loss',
 'NTLM relay attacks require no user interaction — Windows automatically authenticates to what it believes is a legitimate server, handing the attacker a usable credential hash.',
 'Windows is designed to be helpful — it will automatically try to authenticate to servers it sees on the network. Attackers exploit this to capture credentials without any user action.',
 '[{"industry":"Financial Services","description":"NTLM hash captured from a finance server and cracked offline to reveal a service account password."},{"industry":"Government","description":"NTLM relay attack granting immediate access to a domain controller without cracking any credentials."}]',
 ARRAY['NTLM relay attempt detection','Unusual SMB authentication attempts to non-domain systems','Monitoring for responder/Inveigh tool signatures'],
 ARRAY['Disable NTLM where Kerberos is available','Enable SMB signing to prevent relay attacks','Network segmentation to limit broadcast authentication'],
 'Why does enabling SMB signing specifically prevent NTLM relay attacks even when NTLM is still used?',
 'A compromised laptop broadcasts a fake SMB server on the local network. Other Windows systems automatically attempt NTLM authentication, sending their hashed credentials to the attacker.')

ON CONFLICT (technique_id) DO NOTHING;
